from functools import lru_cache
naive_calls=0
def naive(n):
    global naive_calls
    naive_calls+=1
    return n if n<2 else naive(n-1)+naive(n-2)
misses=0
@lru_cache(None)
def memo(n):
    global misses
    misses+=1
    return n if n<2 else memo(n-1)+memo(n-2)
naive(6)
memo(6)
print(naive_calls,misses)

from itertools import combinations
intervals=[(0,3),(3,6),(2,4)]
chosen=[]
for candidate in sorted(intervals,key=lambda t:(t[1]-t[0],t[0])):
    if all(candidate[1]<=x[0] or x[1]<=candidate[0] for x in chosen):
        chosen.append(candidate)
best=0
for n in range(len(intervals)+1):
    for subset in combinations(intervals,n):
        if all(a[1]<=b[0] or b[1]<=a[0] for a,b in combinations(subset,2)):
            best=max(best,n)
print(len(chosen),best)
